cssCode:
.scroll-wrapper { width: 100%; padding: 120vh 0; display: flex; justify-content: center; }
.reveal-box {
  opacity: 0; transform: translateY(80px);
  width: 200px; height: 120px;
  background: linear-gradient(135deg, #ff007f, #7928ca);
  border-radius: 15px; box-shadow: 0 10px 30px rgba(255,0,127,0.5);
  transition: all 0.8s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  display: flex; align-items: center; justify-content: center;
  color: #fff; font-weight: bold; font-family: sans-serif;
}
.reveal-box.visible { opacity: 1; transform: translateY(0); }

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;overflow-y:auto;background:transparent;';

const wrapper = document.createElement('div');
wrapper.className = 'scroll-wrapper';

const box = document.createElement('div');
box.className = 'reveal-box';
box.innerText = 'SCROLL DOWN ↓';

wrapper.appendChild(box);
c.appendChild(wrapper);

const observer = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      entry.target.classList.add('visible');
      entry.target.innerText = 'REVEALED! ✨';
    } else {
      entry.target.classList.remove('visible');
      entry.target.innerText = 'SCROLL DOWN ↓';
    }
  });
});
observer.observe(box);
